// AUTO-GENERATED for the SecEx PoC preview. Holds the exported WXR of the demo
// site and builds a WordPress Playground URL (different origin) that the existing
// SitePreview iframe loads to render the site client-side (Telex-style).

const WXR_B64 =
	'';

export function buildPreviewUrl(): string {
	const wxr = new TextDecoder().decode(
		Uint8Array.from( atob( WXR_B64 ), ( c ) => c.charCodeAt( 0 ) )
	);
	const blueprint = {
		landingPage: '/',
		preferredVersions: { php: '8.3', wp: 'latest' },
		steps: [
			{
				step: 'installTheme',
				themeData: { resource: 'wordpress.org/themes', slug: 'twentytwentyfour' },
				options: { activate: true },
			},
			{ step: 'importWxr', file: { resource: 'literal', name: 'export.xml', contents: wxr } },
			{
				step: 'runPHP',
				code: '<?php require "/wordpress/wp-load.php"; $p=get_page_by_path("inicio"); if($p){update_option("show_on_front","page"); update_option("page_on_front",$p->ID);} ?>',
			},
		],
	};
	// encodeURIComponent (not encodeURI) so `#`, `&`, `=` inside the WXR — e.g.
	// the cover block's `#ff5fa2` color — don't corrupt the URL fragment.
	return 'https://playground.wordpress.net/#' + encodeURIComponent( JSON.stringify( blueprint ) );
}
